/* TimeWorth · interaction prototype 02. All initial records are fictional. */
const M=window.TW,$=s=>document.querySelector(s),h=escapeHTML;
const money=(n,d=0)=>new Intl.NumberFormat('zh-CN',{minimumFractionDigits:d,maximumFractionDigits:d}).format(n);
const yuan=n=>`¥${money(n,2)}`;
const mLabel=m=>`${Number(m.slice(5))}月`;
const dateLabel=d=>d===M.today()?'今天':`${Number(d.slice(5,7))}月${Number(d.slice(8))}日`;
const duration=n=>{const r=M.rate();if(r<=0)return '暂无正向时薪';let min=Math.round(Math.max(0,n)/r*60);return `${Math.floor(min/60)?Math.floor(min/60)+'小时':''}${min%60||!min?min%60+'分钟':''}`;};
const state=()=>M.state;
let tab='home',planTab='repay',ledgerFilter='全部',ledgerAccount='全部',ledgerSearch='',planMonth=M.month(),route=null,stack=[],lastFocus=null,timer;
const navs=[['home','概览','home'],['ledger','账本','book'],['plan','计划','plan'],['profile','我的','user']];
const app=$('#app-content'),sheet=$('#sheet'),backdrop=$('#sheet-backdrop');
function persist(){if(!M.save())toast('浏览器未能保存，请先导出备份');}
function toast(t){$('#toast').textContent=t;$('#toast').classList.add('visible');clearTimeout(timer);timer=setTimeout(()=>$('#toast').classList.remove('visible'),2800);}
const action=(a,label,cls='',extra='')=>`<button class="${cls}" data-action="${a}" ${extra}>${label}</button>`;
const chevron=()=>icon('chevron');
const group=body=>`<div class="group">${body}</div>`;
const row=(label,value,a,extra='',ico='')=>`<button class="list-row" data-action="${a}" ${extra}>${ico?`<span class="row-icon">${icon(ico)}</span>`:''}<span class="row-label">${label}</span><span class="row-value">${value}</span>${chevron()}</button>`;
const note=t=>`<p class="footnote">${t}</p>`;
const section=(name,a='',label='查看全部')=>`<div class="section-title"><h3>${name}</h3>${a?action(a,label,'link'):''}</div>`;
const pill=(label,selected,extra)=>`<button class="pill ${selected?'selected':''}" ${extra} aria-pressed="${selected}">${label}</button>`;
function header(title,tools=''){return `<header class="page-header"><div class="eyeline"><span>${new Date().toLocaleDateString('zh-CN',{month:'long',day:'numeric',weekday:'long'})}</span><span class="demo-dot">体验版 02</span></div><div class="title-line"><h1>${title}</h1><div class="toolbar">${tools}</div></div></header>`;}
function iconButton(a,i,label){return action(a,icon(i),'round-button',`aria-label="${label}"`);}
function transaction(t){return action('transaction',`<span class="tx-icon ${t.type==='refund'?'mint':''}">${icon(t.type==='refund'?'reset':t.icon||'bag')}</span><span class="flex-copy"><strong>${h(t.name)}</strong><small>${h(t.account)} · ${h(t.category)}</small></span><span class="tx-value ${t.type==='refund'?'positive':''}"><strong>${t.type==='refund'?'+':'−'}${yuan(t.amount)}</strong><small>${t.type==='refund'?'退款':duration(t.amount)}</small></span>`,'transaction',`data-id="${h(t.id)}"`);}
function goalCard(g){const b=M.balance(g),pct=Math.min(100,b/g.target*100),left=g.monthly>0?Math.ceil(Math.max(0,g.target-b)/g.monthly):null;return action('goal',`<div class="goal-top"><span class="goal-symbol">${icon(g.icon||'mountain')}</span><div class="flex-copy"><strong>${h(g.name)}</strong><small>${left===0?'心愿已经准备好':left===null?'按自己的节奏存入':`再坚持 ${left} 个月，离它近一点`}</small></div><span class="goal-percent">${money(pct)}<small>%</small></span></div><div class="progress"><i style="width:${pct}%"></i></div><div class="goal-meta"><span>${yuan(b)} <em>/ ${yuan(g.target)}</em></span><span>查看与存入 ${chevron()}</span></div>`,'card goal-card',`data-id="${h(g.id)}"`);}
function home(){const w=state().work,r=M.rate(),a=M.available();return header('时间，值得。',iconButton('notifications','bell','还款提醒')+action('go-profile','时','avatar','aria-label="我的工作"'))+
`<section class="card hourly-card"><div class="hero-top"><span class="metric-label">${icon('clock')} ${w.basis==='real'?'考虑通勤与成本后':'你的到手时薪'}</span>${action('rate','计算方式 '+chevron(),'link')}</div><div class="hourly-value"><span>¥</span>${money(r,2)}<small>/ 小时</small></div><p class="hero-caption">每一笔消费，换一种方式看懂。</p><div class="hero-orbit">${icon('clock')}</div></section>
<div class="quick-actions">${action('calculator',icon('calc')+'算一笔消费','primary')}${action('import',icon('upload')+'导入账单','secondary')}</div>
<div class="stat-grid">${action('go-ledger',`<span class="stat-label">本月净支出 ${chevron()}</span><strong>${yuan(M.spending())}</strong><small>约 ${duration(M.spending())}工作</small>`,'card stat-card')}${action('go-plan',`<span class="stat-label">本月待还 ${chevron()}</span><strong>${yuan(M.due(M.month(),true))}</strong><small>${M.installments().filter(r=>!r.paid).length} 笔待安排</small>`,'card stat-card')}</div>
${section('留给生活的余地','budget','调整预算')}
${action('budget',`<div class="budget-top"><span>本月可自由安排</span><span class="tiny-tag">${mLabel(M.month())}</span></div><div class="budget-value ${a<0?'negative':''}">${a<0?'−':''}¥${money(Math.abs(a),2)}</div><div class="budget-track"><span style="width:${Math.min(90,M.budgetReserved()/Math.max(1,w.salary)*100)}%"></span><i style="width:${Math.min(50,M.due()/Math.max(1,w.salary)*100)}%"></i></div><div class="budget-bottom"><span><i class="dot blue"></i>预算预留 ${yuan(M.budgetReserved())}</span><span><i class="dot purple"></i>分期 ${yuan(M.due())}</span></div>`,'card budget-card')}
${section('最近的日常','go-ledger')}${group(state().transactions.slice().sort((a,b)=>b.date.localeCompare(a.date)).slice(0,2).map(transaction).join(''))}
${section('正在靠近','go-goals','我的目标')}${state().goals[0]?goalCard(state().goals[0]):action('new-goal','＋ 为生活设一个小目标','empty-card')}${note('不是每一次选择，都需要很着急。')}`;}
function ledger(){const records=M.monthlyTx().filter(t=>(ledgerFilter==='全部'||(ledgerFilter==='退款'?t.type==='refund':t.category===ledgerFilter))&&(ledgerAccount==='全部'||t.account===ledgerAccount)&&t.name.toLowerCase().includes(ledgerSearch.toLowerCase())).sort((a,b)=>b.date.localeCompare(a.date)),dates=[...new Set(records.map(t=>t.date))];return header('账本',iconButton('import','upload','导入账单')+iconButton('new-transaction','plus','记一笔'))+
`<section class="card ledger-summary"><span class="metric-label">${mLabel(M.month())}净支出 · 退款已抵扣</span><div class="summary-amount">${yuan(M.spending())}</div><span class="summary-sub">${icon('clock')} 相当于 ${duration(M.spending())}工作</span><div class="spend-bars">${Object.keys(state().budgets).map(c=>`<div><span>${c}</span><i><b style="width:${Math.max(2,Math.min(100,M.spending(M.month(),c)/Math.max(1,state().budgets[c])*100))}%"></b></i><small>${yuan(M.spending(M.month(),c))}</small></div>`).join('')}</div></section>
<div class="search-box">${icon('search')}<input type="search" id="ledger-search" placeholder="搜索这笔日常" aria-label="搜索消费" value="${h(ledgerSearch)}">${action('ledger-account',h(ledgerAccount)+icon('down'),'account-filter')}</div>
<div class="chips">${['全部','日常','购物','居住','退款'].map(c=>pill(c,ledgerFilter===c,`data-filter="${c}"`)).join('')}</div><div id="ledger-records">${dates.length?dates.map(d=>`<div class="date-heading">${dateLabel(d)}<span>${records.filter(t=>t.date===d).length} 笔</span></div>${group(records.filter(t=>t.date===d).map(transaction).join(''))}`).join(''):empty('没有找到记录','记一笔或导入账单，慢慢建立自己的账本。','new-transaction','记一笔')}</div>`;}
function plan(){let amounts=Array.from({length:6},(_,i)=>M.due(M.shiftMonth(M.month(),i),true)),max=Math.max(1,...amounts);const rows=M.installments(planMonth);return header('生活计划',iconButton(planTab==='repay'?'new-debt':planTab==='goals'?'new-goal':'new-wish','plus','新建计划'))+
`<div class="segmented">${[['repay','还款'],['wishes','心愿'],['goals','目标']].map(([key,label])=>`<button class="${planTab===key?'active':''}" data-plan="${key}">${label}</button>`).join('')}</div>`+(planTab==='repay'?`
<div class="month-line">${iconButton('prev-month','chevron','上个月')}<button data-action="select-month">${planMonth.replace('-','年')}月 ${icon('down')}</button>${iconButton('next-month','chevron','下个月')}</div>
<section class="card repay-summary"><span class="metric-label">本月待还</span><div class="summary-amount">${yuan(M.due(planMonth,true))}</div><div class="summary-sub">已还 ${yuan(M.due(planMonth)-M.due(planMonth,true))} · 合计 ${rows.length} 期</div><div class="repay-chart">${amounts.map((a,i)=>`<button data-month="${M.shiftMonth(M.month(),i)}" class="${planMonth===M.shiftMonth(M.month(),i)?'selected':''}" aria-label="${mLabel(M.shiftMonth(M.month(),i))}待还${a}元"><i style="height:${Math.max(3,a/max*64)}px"></i><span>${mLabel(M.shiftMonth(M.month(),i))}</span></button>`).join('')}</div></section>
${section('还款安排','new-debt','添加')}${state().debts.length?state().debts.map(d=>{const rr=d.schedule.filter(r=>r.date.startsWith(planMonth)),unpaid=d.schedule.filter(r=>!r.paid),v=rr.reduce((s,r)=>s+r.total,0);return action('debt',`<div class="debt-head"><span class="platform-logo ${d.name.includes('白条')?'jd':''}">${h(d.name.slice(0,1))}</span><div class="flex-copy"><strong>${h(d.name)}</strong><small>${rr.length?`${Number(rr[0].date.slice(-2))}日到期 · ${rr.every(r=>r.paid)?'本月已还':'待还款'}`:'本月没有应还'}</small></div><strong class="debt-number">${yuan(v)}</strong></div><div class="debt-foot"><span>剩余 ${unpaid.length} 期 · ${yuan(unpaid.reduce((s,r)=>s+r.total,0))}</span><span>管理 ${chevron()}</span></div>`,'card debt-card',`data-id="${h(d.id)}"`);}).join(''):empty('先把还款安排清楚','添加分期后，可以修改金额、费用和还款日。','new-debt','添加分期')}${note('还款单独预留，不再记为一笔消费，避免重复统计。')}`:planTab==='wishes'?`
<div class="intro-line"><h2>喜欢的，慢慢靠近。</h2><p>先收进心愿，想好后再决定。</p></div>${state().wishes.map(w=>action('wish',`<span class="wish-symbol">${icon(w.icon||'bag')}</span><span class="flex-copy"><strong>${h(w.name)}</strong><small>${duration(w.price)}工作 · ${h(w.note||'给未来留一点期待')}</small></span><span class="wish-price">${yuan(w.price)}${chevron()}</span>`,'card wish-card',`data-id="${h(w.id)}"`)).join('')||empty('第一份心愿是什么？','一件小物，或一段想去的旅程。','new-wish','添加心愿')}${action('new-wish','＋ 添加一份心愿','add-line')}`:
`<div class="intro-line"><h2>让期待，有迹可循。</h2><p>存入、调整、取出，都在这里。</p></div>${state().goals.map(goalCard).join('')||empty('给未来一个小目标','每次存入一点，进度都会留下来。','new-goal','建立目标')}${action('new-goal','＋ 建立一个目标','add-line')}`);}
function profile(){const w=state().work;return header('我的',iconButton('about','info','关于体验版'))+`<div class="profile-intro"><span class="profile-avatar">时</span><div><h2>把时间，留给值得。</h2><p>工作与生活，用自己的节奏。</p></div></div>${section('我的工作','work','逐项修改')}${group(row('到手月收入',yuan(w.salary),'work-field','data-key="salary"','wallet')+row('每月工作',`${w.days} 天`,'work-field','data-key="days"','plan')+row('每天工作',`${w.hours} 小时`,'work-field','data-key="hours"','clock')+row('每天往返通勤',`${w.commuteMinutes} 分钟`,'work-field','data-key="commuteMinutes"','plane')+row('每月工作成本',yuan(w.workCost),'work-field','data-key="workCost"','bag'))}${note('点击一项就能修改。通勤默认以分钟记录。')}${section('计算与偏好')}${group(row('时薪计算方式',w.basis==='real'?'含通勤与成本':'仅工作时间','rate','','calc')+row('月度预算','查看与调整','budget','','wallet')+`<button class="list-row" data-action="theme" role="switch" aria-checked="${state().dark}"><span class="row-icon">${icon('moon')}</span><span class="row-label">深色外观</span><span class="switch ${state().dark?'on':''}"></span></button>`)}${section('数据与备份')}${group(row('导入账单','演示 / CSV','import','','upload')+row('导出本机数据','JSON 备份','export','','shield')+row('恢复数据备份','选择 JSON','restore','','reset')+row('体验版说明','参考与边界','about','','info')+row('重置体验数据','','reset','','reset'))}${note('修改保存在当前浏览器。跨设备使用前，请导出备份。')}`;}
function empty(title,desc,a,label){return `<div class="empty"><span>${icon('spark')}</span><h3>${title}</h3><p>${desc}</p>${action(a,label,'secondary')}</div>`;}
function render(keepScroll=true){const top=app.scrollTop;document.body.classList.toggle('dark',state().dark);$('#app-shell').classList.toggle('dark',state().dark);app.innerHTML=({home,ledger,plan,profile})[tab]();$('#tab-bar').innerHTML=navs.map(([key,label,i])=>`<button class="tab ${tab===key?'active':''}" data-tab="${key}" aria-label="${label}" ${tab===key?'aria-current="page"':''}>${icon(i)}<span>${label}</span></button>`).join('');$('#desktop-nav').innerHTML=navs.map(([key,label])=>`<button data-tab="${key}" class="desktop-tab ${tab===key?'active':''}">${label}</button>`).join('');app.scrollTop=keepScroll?top:0;}
function navigate(next){close();tab=next;render(false);}
function open(r,push=true){if(!route){lastFocus=document.activeElement;stack=[];history.pushState({twSheet:true},'');}else if(push)stack.push(route);route=r;renderSheet();}
function close(fromHistory=false){sheet.hidden=true;backdrop.hidden=true;app.inert=false;$('#tab-bar').inert=false;$('#desktop-nav').inert=false;route=null;stack=[];if(!fromHistory&&history.state?.twSheet)history.back();if(lastFocus?.isConnected)lastFocus.focus({preventScroll:true});}
function back(){if(stack.length){route=stack.pop();renderSheet();}else close();}
function sheetChrome(title,body,done='',subtitle=''){return `<div class="sheet-handle"></div><div class="sheet-nav"><button data-action="back" class="sheet-cancel">${stack.length?'返回':'取消'}</button><strong>${title}</strong>${done?action(done,'完成','sheet-done'):action('close',icon('x'),'sheet-close','aria-label="关闭"')}</div><div class="sheet-body">${subtitle?`<p class="sheet-subtitle">${subtitle}</p>`:''}${body}</div>`;}
function renderSheet(){const views={entity:entityView,field:fieldView,calculator:calculatorView,import:importView,review:reviewView,importRecord:importRecordView,goal:goalView,move:moveView,debt:debtView,period:periodView,wish:wishView,confirm:confirmView,rate:rateView,about:aboutView,notifications:notificationsView,choice:choiceView};sheet.innerHTML=views[route.type](route);sheet.hidden=false;backdrop.hidden=false;app.inert=true;$('#tab-bar').inert=true;$('#desktop-nav').inert=true;sheet.scrollTop=0;sheet.focus({preventScroll:true});}
const workFields={salary:{label:'每月到手收入',unit:'元',min:1,max:9999999,step:500,presets:[5000,8000,10000,15000]},days:{label:'每月工作天数',unit:'天',min:1,max:31,step:1,presets:[20,21,22,26]},hours:{label:'每天工作时间',unit:'小时',min:.5,max:24,step:.5,presets:[7.5,8,9,10]},commuteMinutes:{label:'每天往返通勤',unit:'分钟',min:0,max:720,step:5,presets:[0,15,30,45,60,90,120],hint:'填写来回合计时间。例如单程 25 分钟，这里选 50 分钟。'},workCost:{label:'每月额外工作成本',unit:'元',min:0,max:999999,step:50,presets:[0,200,500,800],hint:'只计因为工作额外增加的交通、餐饮等费用。'}};
const schema={work:workFields,budget:Object.fromEntries(['日常','购物','居住'].map(k=>[k,{label:`${k}月预算`,unit:'元',min:0,max:999999,step:100,presets:[500,1000,2000,3000]}])),wish:{name:{label:'心愿名称',text:true,maxLength:40},price:{label:'预计价格',unit:'元',min:.01,max:9999999,step:100},icon:{label:'选择图标',choices:[['headphone','耳机'],['plane','旅行'],['book','学习'],['bag','好物'],['mountain','山海']]},note:{label:'留一句话',text:true,maxLength:100}},goal:{name:{label:'目标名称',text:true,maxLength:40},target:{label:'目标金额',unit:'元',min:1,max:9999999,step:500},monthly:{label:'计划每月存入',unit:'元',min:0,max:999999,step:100,presets:[500,1000,1600,2000]},icon:{label:'选择图标',choices:[['mountain','山海'],['plane','旅行'],['headphone','耳机'],['house','居住'],['book','学习']]}},debt:{name:{label:'分期名称',text:true,maxLength:40},principal:{label:'剩余待分摊本金',unit:'元',min:.01,max:9999999,step:100},terms:{label:'期数',unit:'期',min:1,max:60,step:1,presets:[1,3,6,12,24]},firstMonth:{label:'首期月份',month:true},day:{label:'每月还款日',unit:'日',min:1,max:31,step:1,presets:[1,5,10,15,20,25,28],hint:'遇到不足该日的月份，自动使用月末。'},mode:{label:'费用计算方式',choices:[['zero','免息'],['flat','每期固定费率'],['apr','年利率 · 等额本息']]},rate:{label:'费率',unit:'%',min:0,max:100,step:.1,presets:[0,.3,.6,1,6,12]},upfront:{label:'首期一次性手续费',unit:'元',min:0,max:999999,step:10}},transaction:{name:{label:'消费名称',text:true,maxLength:60},amount:{label:'金额',unit:'元',min:.01,max:9999999,step:10},type:{label:'记录类型',choices:[['expense','支出'],['refund','退款']]},category:{label:'分类',choices:[['日常','日常'],['购物','购物'],['居住','居住']]},account:{label:'支付账户',choices:['支付宝','微信','银行卡','花呗','京东白条','现金'].map(x=>[x,x])},date:{label:'发生日期',date:true}},calculator:{name:{label:'想买什么',text:true,maxLength:40},terms:{label:'分期期数',unit:'期',min:1,max:60,step:1,presets:[3,6,12,24]},mode:{label:'费用计算方式',choices:[['zero','免息'],['flat','每期固定费率'],['apr','年利率 · 等额本息']]},rate:{label:'费率',unit:'%',min:0,max:100,step:.1,presets:[0,.3,.6,1,6,12]},upfront:{label:'首期一次性手续费',unit:'元',min:0,max:999999,step:10},firstMonth:{label:'首期月份',month:true},day:{label:'还款日',unit:'日',min:1,max:31,step:1,presets:[5,10,15,20,25,28]}}};
const entityTitles={work:'我的工作',budget:'月度预算',wish:'编辑心愿',goal:'编辑目标',debt:'编辑分期',transaction:'记一笔日常'};
function newEntity(kind,id){let draft;if(kind==='work')draft=M.clone(state().work);else if(kind==='budget')draft=M.clone(state().budgets);else if(kind==='wish')draft=id?M.clone(state().wishes.find(x=>x.id===id)):{id:M.uid(),name:'我的新心愿',price:1000,icon:'bag',note:''};else if(kind==='goal')draft=id?M.clone(state().goals.find(x=>x.id===id)):{id:M.uid(),name:'给未来的小目标',target:5000,monthly:1000,icon:'mountain',entries:[]};else if(kind==='debt')draft=id?M.clone(state().debts.find(x=>x.id===id)):{id:M.uid(),name:'新的分期',principal:1200,terms:3,firstMonth:M.month(),day:25,mode:'zero',rate:0,upfront:0};else draft=id?M.clone(state().transactions.find(x=>x.id===id)):{id:M.uid(),name:'一笔日常',amount:30,type:'expense',category:'日常',account:'支付宝',date:M.today(),icon:'bag'};return {type:'entity',kind,id,draft};}
function displayField(spec,value){if(spec.choices)return h(spec.choices.find(([k])=>k===value)?.[1]||value);if(spec.month)return h(value.replace('-','年')+'月');if(spec.date)return h(value);if(spec.text)return h(value||'添加一点想法');return `${money(value,Number.isInteger(value)?0:2)}${spec.unit?` <small>${spec.unit}</small>`:''}`;}
function editRows(kind,draft){return Object.entries(schema[kind]).filter(([key])=>!(key==='rate'&&draft.mode==='zero')).map(([key,spec])=>row(key==='rate'?(draft.mode==='apr'?'名义年利率':'每期固定费率'):spec.label,displayField(spec,draft[key]),'edit-field',`data-key="${key}"`)).join('');}
function entityView(r){let hint=r.kind==='work'?'不需要填长表格，点一项就改一项。':r.kind==='debt'?'调整本金、期数或费率会重新生成计划。已还记录需保留时，请逐期编辑金额。':r.kind==='budget'?'预算是预留额度；实际支出超过某类预算后，超出部分会减少可安排金额。':'先点选、再完成，按你的想法慢慢调整。';return sheetChrome(entityTitles[r.kind],group(editRows(r.kind,r.draft))+note(hint)+(r.kind==='debt'?financingPreview(r.draft):'')+(r.kind==='transaction'&&r.id?action('delete-transaction','删除这笔记录','danger full',`data-id="${h(r.id)}"`):''),'save-entity',r.id?'修改后点击右上角完成保存':'每一项都可以点击修改');}
function fieldView(r){const s=r.spec,v=r.parent.draft[r.key],numeric=!s.text&&!s.choices&&!s.month&&!s.date;return sheetChrome(s.label, s.choices?group(s.choices.map(([value,label])=>`<button class="choice-row" data-choice="${h(value)}"><span>${label}</span>${value===v?icon('check'):''}</button>`).join('')):`<div class="single-editor ${s.text?'text-editor':''}"><label for="single-value">${s.hint||s.label}</label>${numeric?`<div class="step-editor">${action('step','−','step','data-dir="-1"')}<div><input id="single-value" type="number" inputmode="decimal" min="${s.min}" max="${s.max}" step="any" value="${v}" aria-label="${s.label}"><span>${s.unit||''}</span></div>${action('step','＋','step','data-dir="1"')}</div>`:`<input id="single-value" type="${s.month?'month':s.date?'date':'text'}" value="${h(v)}" ${s.maxLength?`maxlength="${s.maxLength}"`:''} aria-label="${s.label}">`}${r.key==='commuteMinutes'?`<input type="range" id="minute-slider" min="0" max="180" step="5" value="${Math.min(v,180)}" aria-label="拖动选择往返通勤分钟"><div class="range-label"><span>0 分钟</span><span>180 分钟</span></div>`:''}${s.presets?`<div class="value-presets">${s.presets.map(n=>`<button data-preset="${n}" class="${v===n?'active':''}">${n}<small>${s.unit||''}</small></button>`).join('')}</div>`:''}</div>${note('只修改这一项，不用重新填写其他信息。')}`,'save-field');}
function calculatorDraft(price=2999,name='降噪耳机'){return {type:'calculator',draft:{price,name,terms:1,mode:'flat',rate:.6,upfront:0,firstMonth:M.month(),day:25}};}
function calcFin(d){return M.finance(d.price??d.principal,d.terms,d.terms===1&&'price'in d?'zero':d.mode,d.rate,d.terms===1&&'price'in d?0:d.upfront);}
function financingPreview(d){const f=calcFin(d);return `<div class="fee-summary"><div><span>全部费用</span><strong>${yuan(f.cost)}</strong></div><div><span>合计需还</span><strong>${yuan(f.total)}</strong></div><div><span>按月现金流折算年化</span><strong>${money(f.apr,2)}%</strong></div></div>${note('年化按每月等间隔现金流 IRR × 12 估算，首期收取一次性手续费；不等同于平台披露口径。')}`;}
function calculatorView(r){const d=r.draft;return sheetChrome('算一笔消费',group(row('想买什么',h(d.name),'edit-field','data-key="name"'))+`<div class="price-entry"><label for="calc-price">商品价格</label><div><span>¥</span><input id="calc-price" type="number" inputmode="decimal" min="0.01" max="9999999" step=".01" value="${d.price}" aria-label="商品价格"></div></div><div class="term-options">${[1,3,6,12].map(n=>pill(n===1?'一次付清':`${n} 期`,d.terms===n,`data-terms="${n}"`)).join('')}${action('custom-terms','自定','pill')}</div>${d.terms>1?group(row('期数',`${d.terms} 期`,'edit-field','data-key="terms"')+row('费用方式',displayField(schema.calculator.mode,d.mode),'edit-field','data-key="mode"')+(d.mode!=='zero'?row(d.mode==='apr'?'名义年利率':'每期固定费率',`${d.rate}%`,'edit-field','data-key="rate"'):'')+row('首期手续费',yuan(d.upfront),'edit-field','data-key="upfront"')+row('首期月份',d.firstMonth,'edit-field','data-key="firstMonth"')+row('还款日',`${d.day} 日`,'edit-field','data-key="day"')):''}<div id="calc-results">${calcResults(d)}</div>${action('calc-to-plan',d.terms>1?'加入还款计划':'存为心愿','primary full')}${d.terms>1?action('calc-to-wish','先收进心愿，再想想','text-button full'):''}${note('费率为可编辑示例，实际利息、服务费和还款时间以平台为准。')}`);}
function calcResults(d){const f=calcFin(d),first=f.rows[0]?.total||0,base=M.available(),thisMonth=d.terms===1||d.firstMonth===M.month()?first:0,remaining=base-thisMonth;return `<div class="time-result"><span>连同费用，相当于</span><strong>${duration(f.total)}<small>工作收入</small></strong><p>按${state().work.basis==='real'?'含通勤与成本':'到手'}时薪 ${yuan(M.rate())} 计算</p></div>${group(`<div class="plain-row"><span>${d.terms>1?'首期需还':'本次支付'}</span><strong>${yuan(first)}</strong></div><div class="plain-row"><span>本月可安排将剩余</span><strong class="${remaining<0?'negative':''}">${yuan(remaining)}</strong></div>`)}${d.terms>1?financingPreview(d)+`<details class="schedule-details"><summary>查看每一期本金与费用 ${icon('down')}</summary><div class="schedule-table"><div class="schedule-line heading"><span>期数 / 日期</span><span>本金</span><span>息费</span><span>应还</span></div>${f.rows.map((p,i)=>`<div class="schedule-line"><span>${i+1} · ${M.dueDate(M.shiftMonth(d.firstMonth,i),d.day).slice(5)}</span><span>${money(p.principal,2)}</span><span>${money(p.interest+p.fee,2)}</span><strong>${money(p.total,2)}</strong></div>`).join('')}</div></details>`:''}`;}
function debtView(r){const d=state().debts.find(x=>x.id===r.id);if(!d)return sheetChrome('还款计划',note('这份计划已移除。'));const total=d.schedule.filter(x=>!x.paid).reduce((s,x)=>s+x.total,0);return sheetChrome(h(d.name),`<div class="detail-hero"><span>剩余待还</span><strong>${yuan(total)}</strong><small>本金 ${yuan(d.principal)} · ${d.terms} 期</small></div><div class="detail-actions">${action('edit-debt',icon('edit')+'调整计划','secondary',`data-id="${h(d.id)}"`)}</div>${note('点一行可修改该期金额或还款日；右侧圆圈标记已还 / 待还。')}${group(d.schedule.map((p,i)=>`<div class="period-row"><button class="period-open" data-action="period" data-id="${h(d.id)}" data-period="${p.id}"><span class="period-num">${i+1}</span><span class="flex-copy"><strong>${p.date}</strong><small>本金 ${yuan(p.principal)} · 息费 ${yuan(p.interest+p.fee)}</small></span><strong>${yuan(p.total)}</strong></button><button class="paid-check ${p.paid?'checked':''}" data-action="paid" data-id="${h(d.id)}" data-period="${p.id}" aria-label="第${i+1}期${p.paid?'撤销已还':'标记已还'}" aria-pressed="${p.paid}">${p.paid?icon('check'):''}</button></div>`).join(''))}${action('delete-debt','删除这份计划','danger full',`data-id="${h(d.id)}"`)}`);}
function periodView(r){const d=r.draft;return sheetChrome('调整这一期',`<div class="compact-input"><label for="period-date">还款日期</label><input type="date" id="period-date" value="${d.date}" required></div><div class="compact-input"><label for="period-principal">本期本金（元）</label><input type="number" inputmode="decimal" id="period-principal" value="${d.principal}" min="0" max="9999999" step=".01"></div><div class="compact-input"><label for="period-cost">本期利息和手续费（元）</label><input type="number" inputmode="decimal" id="period-cost" value="${M.round(d.interest+d.fee)}" min="0" max="9999999" step=".01"></div>${note('修改仅作用于这一期，不改动其他期次，也不影响已还状态。')}`,'save-period');}
function wishView(r){const w=state().wishes.find(x=>x.id===r.id);if(!w)return sheetChrome('心愿',note('这份心愿已移除。'));return sheetChrome('我的心愿',`<div class="wish-hero"><span>${icon(w.icon)}</span><h2>${h(w.name)}</h2><strong>${yuan(w.price)}</strong><p>${h(w.note||'喜欢的东西，值得想清楚再决定。')}</p><small>相当于 ${duration(w.price)}工作收入</small></div>${group(row('修改心愿','名称、价格与想法','edit-wish',`data-id="${h(w.id)}"`)+row('算一算分期','包含利息和手续费','wish-calc',`data-id="${h(w.id)}"`))}${action('wish-to-goal','为它建立存钱目标','primary full',`data-id="${h(w.id)}"`)}${action('delete-wish','移除心愿','danger full',`data-id="${h(w.id)}"`)}`);}
function goalView(r){const g=state().goals.find(x=>x.id===r.id);if(!g)return sheetChrome('目标',note('这个目标已移除。'));const b=M.balance(g),pct=Math.min(100,b/g.target*100);return sheetChrome(h(g.name),`<div class="goal-detail"><div class="goal-ring" style="--progress:${pct}%"><div><strong>${money(pct)}<small>%</small></strong><span>一步步靠近</span></div></div><p>已存 ${yuan(b)} <span>/ ${yuan(g.target)}</span></p></div><div class="detail-actions">${action('deposit','＋ 存入一笔','primary',`data-id="${h(g.id)}"`)}${action('withdraw','取出','secondary',`data-id="${h(g.id)}"`)}</div>${group(row('调整目标','名称、金额、月计划','edit-goal',`data-id="${h(g.id)}"`)+`<div class="plain-row"><span>计划每月存入</span><strong>${yuan(g.monthly)}</strong></div>`)}${section('每一步都算数')}${group(g.entries.slice().reverse().map(e=>`<div class="entry-row"><span><strong>${e.amount>=0?'存入':'取出'} ${yuan(Math.abs(e.amount))}</strong><small>${e.date} · ${h(e.note||'为未来留一点')}</small></span>${e.id==='opening'?'<small class="muted">初始存款</small>':action('delete-entry',icon('x'),'small-icon',`data-id="${h(g.id)}" data-entry="${h(e.id)}" aria-label="删除这笔${e.amount>=0?'存入':'取出'}"`)}</div>`).join(''))}${note('本月存入会减少首页可安排金额；取出会释放。已有历史存款不再重复扣除。')}${action('delete-goal','删除目标','danger full',`data-id="${h(g.id)}"`)}`);}
function moveView(r){const g=state().goals.find(x=>x.id===r.id);return sheetChrome(r.withdraw?'从目标中取出':'为期待存入一点',`<div class="move-intro">${icon('mountain')}<h2>${h(g.name)}</h2><p>目前已存 ${yuan(M.balance(g))}</p></div><div class="price-entry"><label for="move-amount">${r.withdraw?'取出':'存入'}金额</label><div><span>¥</span><input id="move-amount" type="number" inputmode="decimal" min=".01" max="9999999" value="200" aria-label="金额"></div></div><div class="value-presets">${[100,200,500,1000].map(n=>`<button data-move-preset="${n}">${n}<small>元</small></button>`).join('')}</div><div class="compact-input"><label for="move-note">留句话（选填）</label><input id="move-note" maxlength="80" placeholder="例如，少喝两杯咖啡"></div>${note('这里只记录存钱进度，不会发起真实转账。')}`,'save-move');}
const sources=['支付宝','微信','花呗','京东白条'];
function demoRecords(source){const base=[{name:'便利店的日常补给',amount:20.9,type:'expense',category:'日常',date:M.today(),account:source,order:'new-demo-'+source},{name:source==='微信'?'一顿好好吃的午饭':'街角咖啡',amount:source==='微信'?38:24,type:'expense',category:'日常',date:M.today(),account:source,order:source==='微信'?'lunch-demo':'coffee-demo'},{name:'订单退款',amount:79,type:'refund',category:'购物',date:M.today(),account:source,order:'refund-demo-'+source}];if(source==='花呗'||source==='京东白条')base[0]={...base[0],name:source+'本月应还',amount:source==='花呗'?720:540,type:'repayment',order:'repayment-'+source};return base.map(t=>({...t,id:M.uid(),key:M.fingerprint(t),selected:!M.duplicate({...t,key:M.fingerprint(t)}),force:false}));}
function importView(r){return sheetChrome('导入账单',`<div class="import-intro"><span>${icon('upload')}</span><h2>把日常，放在一起。</h2><p>先选来源，再核对记录。<br>文件只在这个浏览器里解析。</p></div><div class="source-grid">${sources.map((s,i)=>`<button data-source="${s}"><span class="source-mark source-${i}">${s.slice(0,1)}</span><strong>${s}</strong><small>核对体验 ${chevron()}</small></button>`).join('')}</div>${action('choose-csv',icon('upload')+'选择 CSV 账单文件','primary full')}${action('download-csv','下载标准 CSV 样例','text-button full')}${note('支持标准 CSV，以及可识别表头的支付宝 / 微信 CSV。花呗、白条的 PDF、截图和各版账单仍需适配；可先用标准 CSV 录入，或点击上方体验。')}`);}
function reviewView(r){const count=r.records.filter(x=>x.selected).length;return sheetChrome('核对导入记录',`${r.demo?`<div class="source-scroll">${sources.map(s=>pill(s,s===r.source,`data-review-source="${s}"`)).join('')}</div>`:`<div class="import-file-label">${icon('book')} ${h(r.filename)} · ${h(r.source)}</div>`}<div class="review-header"><div><strong>${r.records.length} 笔记录</strong><span>已选 ${count} 笔</span></div><button class="link" data-action="select-records">${count===r.records.length?'取消全选':'全选'}</button></div>${r.warning?note(h(r.warning)):''}<div class="review-list">${r.records.map((t,i)=>{const dup=M.duplicate(t),merge=t.type==='repayment'&&findDebtForImport(t);return `<div class="review-record ${t.selected?'is-selected':''}"><label class="record-check"><input type="checkbox" data-record="${i}" ${t.selected?'checked':''} aria-label="选择${h(t.name)}"><span>${icon('check')}</span></label><button class="record-edit" data-action="review-record" data-index="${i}"><span class="flex-copy"><strong>${h(t.name)}</strong><small>${t.date} · ${t.type==='refund'?'退款':t.type==='repayment'?'还款计划':h(t.category)}</small><span class="record-tag ${dup?'amber':t.type==='refund'?'purple':''}">${dup?'疑似重复 · 可选择处理':t.type==='refund'?'退款 · 可勾选并核对':merge?'已有计划 · 将更新本期金额':'可导入'}</span></span><span class="record-amount">${t.type==='refund'?'+':''}${yuan(t.amount)}${chevron()}</span></button></div>`;}).join('')}</div>${note('每一条都可以选择或修改。选中疑似重复项后，需要明确选择处理方式；还款更新计划，不计为消费。')}${action('confirm-import',`导入已选的 ${count} 笔`,'primary full',count?'':'disabled')}${r.demo?note('当前为演示记录；切换来源可体验不同账单。'):note('导入后会保存到当前浏览器，不上传到服务器。')}`);}
function importRecordView(r){const t=r.draft,dup=M.duplicate(t);return sheetChrome('核对这一笔',group(row('名称',h(t.name),'import-field','data-key="name"')+row('金额',yuan(t.amount),'import-field','data-key="amount"')+row('日期',t.date,'import-field','data-key="date"')+row('记录类型',{'expense':'支出','refund':'退款','repayment':'还款计划'}[t.type],'import-field','data-key="type"')+row('分类',h(t.category),'import-field','data-key="category"'))+(dup?`<div class="review-warning">${icon('info')}<div><strong>找到疑似重复记录</strong><p>默认跳过；只有确认是不同交易，才保留为新记录。</p></div></div>${group(`<button class="list-row" data-action="toggle-force" role="switch" aria-checked="${t.force}"><span class="row-label">确认保留为独立记录</span><span class="switch ${t.force?'on':''}"></span></button>`)}`:'')+note('退款会抵扣分类净支出；还款只更新计划，避免和原消费重复。'),'save-import-record');}
function findDebtForImport(t){return state().debts.find(d=>(d.name===t.account||d.name===t.name)&&d.schedule.some(p=>p.date.startsWith(t.date.slice(0,7))));}
function confirmView(r){return sheetChrome(r.title,`<div class="confirm-copy"><h2>${r.title}</h2><p>${r.message}</p></div>${action('confirm-operation',r.label||'确认删除',r.danger===false?'primary full':'danger filled full')}${action('back','保留，返回','secondary full')}`);}
function choiceView(r){return sheetChrome(r.title,group(r.options.map(([value,label])=>`<button class="choice-row" data-menu-choice="${h(value)}">${h(label)}${r.value===value?icon('check'):''}</button>`).join('')));}
function rateView(){const w=state().work;return sheetChrome('一小时的价值',`<div class="rate-hero"><span>当前用于消费换算</span><strong>${yuan(M.rate())}<small>/ 小时</small></strong></div>${group([['work','仅工作时间',`${yuan(w.salary)} ÷ ${w.days}天 ÷ ${w.hours}小时`],['real','含通勤与额外成本',`(${yuan(w.salary)} − ${yuan(w.workCost)}) ÷ ${w.days}天 ÷ (${w.hours}小时 + ${w.commuteMinutes}分钟)`]].map(([key,title,desc])=>`<button class="rate-option" data-basis="${key}"><span class="radio ${w.basis===key?'on':''}"></span><span><strong>${title}</strong><small>${desc}</small><b>${yuan(M.rate(key))}<em>/ 小时</em></b></span></button>`).join(''))}${note('选择后，首页、账本、心愿和消费换算都会采用同一口径。若工作成本超过收入，工作时间无法换算，将显示提示。')}${action('work','修改工作信息','secondary full')}`);}
function aboutView(){return sheetChrome('关于这一版',`<div class="about-brand"><span class="brand-mark">t<span>·</span></span><h2>TimeWorth</h2><p>时间有价，生活有序。</p><span class="tiny-tag">交互体验版 02</span></div>${group(`<div class="info-copy"><h3>可以实际操作</h3><p>逐项编辑工作信息、CSV 核对导入、还款逐期调整、心愿与目标、存入取出、分期息费测算、数据备份与恢复。</p></div><div class="info-copy"><h3>现在的边界</h3><p>初始数据与费率均为示例。修改仅存当前浏览器；没有连接支付账户、发起扣款或系统通知。安卓 APK、自动同步、PDF/OCR 与平台专用账单适配尚未实现。</p></div>`)}${section('设计与交互参考')}${group(`<a class="list-row" href="https://developer.apple.com/design/human-interface-guidelines/materials" target="_blank" rel="noopener"><span class="row-label">Apple · Materials</span>${chevron()}</a><a class="list-row" href="https://github.com/jameskokoska/Cashew" target="_blank" rel="noopener"><span class="row-label">Cashew · 开源记账</span>${chevron()}</a>`)}${note('参考信息层级、按需编辑和目标记录。此网页使用自行实现的代码，没有复制上述项目代码或 Apple 品牌素材。')}`);}
function notificationsView(){const items=M.installments().filter(p=>!p.paid).sort((a,b)=>a.date.localeCompare(b.date));return sheetChrome('接下来的安排',items.length?group(items.map(p=>row(h(p.name),`${p.date.slice(5)} · ${yuan(p.total)}`,'debt',`data-id="${h(p.debtId)}"`)).join('')):note('这个月的还款都安排好了。'));}
function openField(parent,key,spec){open({type:'field',parent,key,spec:spec||schema[parent.kind||'calculator'][key]});}
function returnParent(){route=stack.pop()||null;if(route)renderSheet();else close();}
function refreshAll(){render();if(route)renderSheet();}
function entitySave(){const r=route,d=r.draft;if(r.kind==='work'){Object.assign(state().work,d);}else if(r.kind==='budget'){Object.assign(state().budgets,d);}else{let collection={wish:'wishes',goal:'goals',debt:'debts',transaction:'transactions'}[r.kind],value=d;if(r.kind==='debt'){const old=state().debts.find(x=>x.id===r.id),changed=!old||['principal','terms','mode','rate','upfront','firstMonth','day'].some(k=>old[k]!==d[k]);value=changed?M.makeDebt(d):d;}const index=state()[collection].findIndex(x=>x.id===d.id);if(index>=0)state()[collection][index]=value;else state()[collection].unshift(value);}
  persist();close();if(r.kind==='debt'){tab='plan';planTab='repay';planMonth=d.firstMonth;}else if(r.kind==='wish'){tab='plan';planTab='wishes';}else if(r.kind==='goal'){tab='plan';planTab='goals';}else if(r.kind==='transaction')tab='ledger';render();toast('已保存，相关数据同步更新');}
function numericValue(id,min,max){const v=Number($(id).value);if(!$(id).value||!Number.isFinite(v)||v<min||v>max)throw new Error(`请输入 ${min} 到 ${max} 之间的数值`);return M.round(v);}
function confirmDelete(collection,id,kind){const name=state()[collection].find(x=>x.id===id)?.name;open({type:'confirm',title:`删除${kind}？`,message:`“${h(name||kind)}”及其相关记录将从本机数据中移除。可以先在“我的”中导出备份。`,operation:()=>{state()[collection]=state()[collection].filter(x=>x.id!==id);persist();close();render();toast('已删除');}});}
function download(data,name,type='application/json'){const url=URL.createObjectURL(new Blob([data],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function chooseFile(accept,handler){const input=document.createElement('input');input.type='file';input.accept=accept;input.onchange=async()=>{if(input.files[0])try{await handler(input.files[0]);}catch(e){toast(e.message||'文件读取失败');}};input.click();}
function parseCSV(text){const rows=[];let row=[],cell='',quoted=false;text=text.replace(/^\uFEFF/,'');for(let i=0;i<text.length;i++){const c=text[i];if(c==='"'){if(quoted&&text[i+1]==='"'){cell+='"';i++;}else quoted=!quoted;}else if(c===','&&!quoted){row.push(cell.trim());cell='';}else if((c==='\n'||c==='\r')&&!quoted){if(c==='\r'&&text[i+1]==='\n')i++;row.push(cell.trim());if(row.some(Boolean))rows.push(row);row=[];cell='';}else cell+=c;}if(quoted)throw new Error('CSV 引号没有闭合，请检查文件');row.push(cell.trim());if(row.some(Boolean))rows.push(row);return rows;}
async function readCSV(file){if(file.size>2*1024*1024)throw new Error('请使用小于 2MB 的 CSV 文件');let bytes=await file.arrayBuffer(),text=new TextDecoder('utf-8').decode(bytes);if(text.includes('\uFFFD'))text=new TextDecoder('gb18030').decode(bytes);const rows=parseCSV(text);const hi=rows.findIndex(r=>r.some(c=>/^(日期|交易时间|交易创建时间|时间)$/.test(c))&&r.some(c=>/金额/.test(c)));if(hi<0)throw new Error('未识别到日期和金额列，请使用标准 CSV 样例');const headers=rows[hi],pick=(r,keys)=>{const i=headers.findIndex(c=>keys.includes(c));return i>=0?r[i]||'':'';},account=headers.includes('交易对方')&&headers.includes('商品')?'微信':headers.includes('交易创建时间')?'支付宝':route?.source||'支付宝';let skipped=0,records=[];
for(const r of rows.slice(hi+1)){const amount=Number(pick(r,['金额','金额(元)','金额（元）']).replace(/[¥￥,]/g,'')),rawDate=pick(r,['日期','交易时间','交易创建时间','时间']).replaceAll('/','-'),match=rawDate.match(/^(\d{4})-(\d{1,2})-(\d{1,2})/),status=pick(r,['当前状态','交易状态']),kind=pick(r,['类型','收/支','收支','收/支/其他']),name=pick(r,['名称','商品名称','商品说明','商品','交易对方'])||'导入的记录',isRefund=/退款/.test(kind+status+name),type=isRefund?'refund':/还款/.test(kind+name)?'repayment':'expense';
if(!match||!Number.isFinite(amount)||amount<=0||/关闭|失败/.test(status)||(type!=='repayment'&&!isRefund&&/收入|不计收支|不计收入/.test(kind))){skipped++;continue;}const date=`${match[1]}-${match[2].padStart(2,'0')}-${match[3].padStart(2,'0')}`;if(Number.isNaN(Date.parse(date))||date!==M.dueDate(date.slice(0,7),Number(match[3]))){skipped++;continue;}let t={id:M.uid(),name:name.slice(0,60),amount:M.round(amount),date,type,category:['日常','购物','居住'].includes(pick(r,['分类']))?pick(r,['分类']):'日常',account:pick(r,['账户','来源'])||account,order:pick(r,['订单号','交易号','交易订单号','商户单号'])};t.key=M.fingerprint(t);t.selected=!M.duplicate(t);t.force=false;records.push(t);if(records.length>1000)throw new Error('每次最多核对 1000 笔，请拆分文件');}
if(!records.length)throw new Error('没有可导入的支出、退款或还款记录');open({type:'review',source:account,filename:file.name,demo:false,records,warning:skipped?`已略过 ${skipped} 行：无效金额、失败交易、普通收入或说明行。`:''});}
function importSelected(r){const selected=r.records.filter(t=>t.selected),blocked=selected.find(t=>M.duplicate(t)&&!t.force);if(blocked){const index=r.records.indexOf(blocked);open({type:'importRecord',parent:r,index,draft:M.clone(blocked)});toast('请先确认这笔疑似重复记录');return;}const inBatch=new Set();let count=0;
for(const item of selected){const t=M.clone(item);if((M.duplicate(t)||inBatch.has(t.key))&&!t.force)continue;inBatch.add(t.key);if(t.type==='repayment'){let d=findDebtForImport(t);if(d){let p=d.schedule.find(p=>p.date.startsWith(t.date.slice(0,7)));const previousPrincipal=p.principal;p.principal=M.round(Math.max(0,t.amount-p.interest-p.fee));if(t.amount<p.interest+p.fee){p.principal=0;p.interest=t.amount;p.fee=0;}p.total=t.amount;p.paid=false;d.principal=M.round(d.principal+p.principal-previousPrincipal);}else state().debts.push(M.makeDebt({id:M.uid(),name:t.account,principal:t.amount,terms:1,firstMonth:t.date.slice(0,7),day:Number(t.date.slice(8)),mode:'zero',rate:0,upfront:0}));}else{delete t.selected;delete t.force;delete t.key;t.id=M.uid();state().transactions.unshift(t);}state().imports.push(item.key);count++;}
persist();navigate('ledger');toast(`已导入 ${count} 笔，支出与还款分别统计`);}
// All prototype actions live in one delegated handler; drafts stay in memory until Done.
document.addEventListener('click',async event=>{const b=event.target.closest('button');if(!b)return;try{
if(b.dataset.tab){navigate(b.dataset.tab);return;}
if(b.dataset.filter){ledgerFilter=b.dataset.filter;render();return;}
if(b.dataset.plan){planTab=b.dataset.plan;render();return;}
if(b.dataset.month){planMonth=b.dataset.month;render();return;}
if(b.dataset.source){open({type:'review',demo:true,source:b.dataset.source,records:demoRecords(b.dataset.source)});return;}
if(b.dataset.reviewSource){route.source=b.dataset.reviewSource;route.records=demoRecords(route.source);renderSheet();return;}
if(b.dataset.terms){if(!validateCalculator())return;route.draft.terms=Number(b.dataset.terms);renderSheet();return;}
if(b.dataset.choice!==undefined){route.parent.draft[route.key]=b.dataset.choice;returnParent();return;}
if(b.dataset.preset){$('#single-value').value=b.dataset.preset;if($('#minute-slider'))$('#minute-slider').value=b.dataset.preset;return;}
if(b.dataset.movePreset){$('#move-amount').value=b.dataset.movePreset;return;}
if(b.dataset.basis){state().work.basis=b.dataset.basis;persist();refreshAll();return;}
if(b.dataset.menuChoice!==undefined){const callback=route.onChoose;callback(b.dataset.menuChoice);return;}
const a=b.dataset.action,id=b.dataset.id;
if(a==='close')close();else if(a==='back')back();else if(a==='go-profile')navigate('profile');else if(a==='go-ledger')navigate('ledger');else if(a==='go-plan'){planTab='repay';navigate('plan');}else if(a==='go-goals'){planTab='goals';navigate('plan');}
else if(a==='calculator')open(calculatorDraft());else if(a==='import')open({type:'import'});else if(a==='rate')open({type:'rate'});else if(a==='about')open({type:'about'});else if(a==='notifications')open({type:'notifications'});
else if(a==='work'||a==='budget')open(newEntity(a));else if(a==='work-field'){const parent=newEntity('work');parent.direct=true;open(parent);openField(parent,b.dataset.key);}
else if(a==='edit-field'){if(route.type==='calculator'&&!validateCalculator())return;openField(route,b.dataset.key);}
else if(a==='custom-terms'){if(validateCalculator())openField(route,'terms');}
else if(a==='step'){const v=$('#single-value'),s=route.spec;v.value=M.round(Math.min(s.max,Math.max(s.min,Number(v.value)+Number(b.dataset.dir)*s.step)));if($('#minute-slider'))$('#minute-slider').value=v.value;}
else if(a==='save-field'){const s=route.spec;let value;if(s.choices){back();return;}else if(s.text){value=$('#single-value').value.trim();if(!value&&route.key!=='note')throw new Error('请给它起一个名字');}else if(s.date||s.month){value=$('#single-value').value;if(!value)throw new Error('请选择日期');}else{value=numericValue('#single-value',s.min,s.max);if(['terms','days','day','commuteMinutes'].includes(route.key)&&!Number.isInteger(value))throw new Error('这一项请使用整数');}route.parent.draft[route.key]=value;const direct=route.parent.direct;returnParent();if(direct)entitySave();}
else if(a==='save-entity'){if(route.kind==='debt'&&route.id){const old=state().debts.find(d=>d.id===route.id),changed=['principal','terms','mode','rate','upfront','firstMonth','day'].some(k=>old[k]!==route.draft[k]);if(changed&&old.schedule.some(x=>x.paid)){const parent=route;open({type:'confirm',title:'重新生成还款计划？',message:'本金、期数或费率变化会生成全新计划，原计划的已还状态也会重置。保留已还状态可返回逐期修改。',label:'重新生成',danger:false,operation:()=>{route=parent;entitySave();}});return;}}entitySave();}
else if(a==='delete-transaction')confirmDelete('transactions',id,'记录');else if(a==='new-transaction')open(newEntity('transaction'));else if(a==='transaction')open(newEntity('transaction',id));
else if(a==='new-debt')open(newEntity('debt'));else if(a==='debt')open({type:'debt',id});else if(a==='edit-debt')open(newEntity('debt',id));
else if(a==='period'){const d=state().debts.find(x=>x.id===id),p=d.schedule.find(x=>x.id===b.dataset.period);open({type:'period',debtId:id,periodId:p.id,draft:M.clone(p)});}
else if(a==='save-period'){const d=state().debts.find(x=>x.id===route.debtId),p=d.schedule.find(x=>x.id===route.periodId),principal=numericValue('#period-principal',0,9999999),cost=numericValue('#period-cost',0,9999999),date=$('#period-date').value;if(!date)throw new Error('请选择还款日期');d.principal=M.round(d.principal+principal-p.principal);Object.assign(p,{principal,interest:cost,fee:0,total:M.round(principal+cost),date});persist();returnParent();render();toast('本期金额与日期已更新');}
else if(a==='paid'){const p=state().debts.find(x=>x.id===id).schedule.find(x=>x.id===b.dataset.period);p.paid=!p.paid;persist();refreshAll();toast(p.paid?'已标记还款，消费不会重复记账':'已恢复为待还');}
else if(a==='delete-debt')confirmDelete('debts',id,'还款计划');
else if(a==='prev-month'||a==='next-month'){planMonth=M.shiftMonth(planMonth,a==='next-month'?1:-1);render();}
else if(a==='select-month')open({type:'choice',title:'选择月份',value:planMonth,options:Array.from({length:18},(_,i)=>{const m=M.shiftMonth(M.month(),i-6);return [m,m.replace('-','年')+'月'];}),onChoose:v=>{planMonth=v;close();render();}});
else if(a==='new-wish')open(newEntity('wish'));else if(a==='wish')open({type:'wish',id});else if(a==='edit-wish')open(newEntity('wish',id));else if(a==='wish-calc'){const w=state().wishes.find(x=>x.id===id);open(calculatorDraft(w.price,w.name));}
else if(a==='wish-to-goal'){const w=state().wishes.find(x=>x.id===id),r=newEntity('goal');r.draft.name=w.name;r.draft.target=w.price;r.draft.icon=w.icon;open(r);}
else if(a==='delete-wish')confirmDelete('wishes',id,'心愿');
else if(a==='new-goal')open(newEntity('goal'));else if(a==='goal')open({type:'goal',id});else if(a==='edit-goal')open(newEntity('goal',id));else if(a==='delete-goal')confirmDelete('goals',id,'目标');
else if(a==='deposit'||a==='withdraw')open({type:'move',id,withdraw:a==='withdraw'});
else if(a==='save-move'){const g=state().goals.find(x=>x.id===route.id),amount=numericValue('#move-amount',.01,9999999);if(route.withdraw&&amount>M.balance(g))throw new Error('取出金额不能超过已存金额');if(!route.withdraw&&M.available()<amount){const parent=route,note=$('#move-note').value.trim();open({type:'confirm',title:'本月可安排金额不足',message:`存入 ${yuan(amount)} 后，可安排金额将为 ${yuan(M.available()-amount)}。仍要记录这笔存入吗？`,label:'仍然记录',danger:false,operation:()=>{g.entries.push({id:M.uid(),amount,date:M.today(),note});persist();close();planTab='goals';navigate('plan');toast('存入已记录');}});return;}g.entries.push({id:M.uid(),amount:route.withdraw?-amount:amount,date:M.today(),note:$('#move-note').value.trim()});persist();returnParent();render();toast('进度已更新');}
else if(a==='delete-entry'){const g=state().goals.find(x=>x.id===id),entry=b.dataset.entry,record=g.entries.find(x=>x.id===entry);if(M.balance(g)-record.amount<0)throw new Error('这笔存入已有后续取出，请先调整对应的取出记录');open({type:'confirm',title:'删除这笔记录？',message:'目标进度与本月预留金额会同步重新计算。',operation:()=>{g.entries=g.entries.filter(x=>x.id!==entry);persist();back();render();toast('记录已移除');}});}
else if(a==='calc-to-wish'||a==='calc-to-plan'){if(!validateCalculator())return;const d=route.draft;if(a==='calc-to-wish'||d.terms===1){state().wishes.unshift({id:M.uid(),name:d.name,price:d.price,icon:'bag',note:''});persist();planTab='wishes';navigate('plan');toast('心愿已收好');}else{const entity=newEntity('debt');entity.draft={...entity.draft,name:d.name,principal:d.price,terms:d.terms,mode:d.mode,rate:d.rate,upfront:d.upfront,day:d.day,firstMonth:d.firstMonth};open(entity);}}
else if(a==='theme'){state().dark=!state().dark;persist();render();}
else if(a==='ledger-account')open({type:'choice',title:'选择支付账户',value:ledgerAccount,options:['全部',...new Set(state().transactions.map(t=>t.account))].map(x=>[x,x]),onChoose:v=>{ledgerAccount=v;close();render();}});
else if(a==='select-records'){const select=route.records.some(x=>!x.selected);route.records.forEach(x=>x.selected=select);renderSheet();}
else if(a==='review-record'){const index=Number(b.dataset.index);open({type:'importRecord',parent:route,index,draft:M.clone(route.records[index])});}
else if(a==='import-field'){let spec=b.dataset.key==='type'?{label:'记录类型',choices:[['expense','支出'],['refund','退款'],['repayment','还款计划']]}:schema.transaction[b.dataset.key];openField(route,b.dataset.key,spec);}
else if(a==='toggle-force'){route.draft.force=!route.draft.force;renderSheet();}
else if(a==='save-import-record'){const r=route;r.parent.records[r.index]={...r.draft,selected:true};returnParent();}
else if(a==='confirm-import')importSelected(route);
else if(a==='choose-csv')chooseFile('.csv,text/csv',readCSV);
else if(a==='download-csv')download('\uFEFF日期,名称,金额,类型,分类,账户,订单号\n'+M.today()+',便利店,20.90,支出,日常,支付宝,example-001\n'+M.today()+',退回一件好物,79,退款,购物,支付宝,example-refund\n','timeworth-import-example.csv','text/csv;charset=utf-8');
else if(a==='export')download(JSON.stringify({app:'TimeWorth',version:2,exportedAt:new Date().toISOString(),data:state()},null,2),`timeworth-backup-${M.today()}.json`);
else if(a==='restore')chooseFile('.json,application/json',async file=>{if(file.size>5*1024*1024)throw new Error('备份文件需小于 5MB');const data=JSON.parse(await file.text());validateBackup(data);open({type:'confirm',title:'恢复这份备份？',message:'当前浏览器的数据将被这份 TimeWorth 备份替换。建议先导出现有数据。',label:'恢复备份',danger:false,operation:()=>{Object.assign(state(),data.data);persist();navigate('home');toast('备份已恢复');}});});
else if(a==='reset')open({type:'confirm',title:'重新开始体验？',message:'将清除本机的修改、导入、心愿和目标，恢复演示初始数据。建议先导出备份。',label:'恢复初始数据',operation:()=>{M.reset();navigate('home');toast('演示已恢复');}});
else if(a==='confirm-operation')route.operation();
}catch(e){toast(e.message||'操作没有完成，请检查输入');}});
function validateCalculator(){try{route.draft.price=numericValue('#calc-price',.01,9999999);return true;}catch(e){toast(e.message);return false;}}
function validateBackup(payload){const d=payload?.data;if(payload.app!=='TimeWorth'||d?.version!==2)throw new Error('请选择 TimeWorth 第 2 版数据备份');const positive=(n,max=9999999)=>typeof n==='number'&&Number.isFinite(n)&&n>0&&n<=max,nonnegative=n=>typeof n==='number'&&Number.isFinite(n)&&n>=0&&n<=99999999,text=(s,max=100)=>typeof s==='string'&&s.length<=max,date=s=>typeof s==='string'&&/^\d{4}-\d{2}-\d{2}$/.test(s)&&!Number.isNaN(Date.parse(s));if(!positive(d.work?.salary)||!positive(d.work.days,31)||!positive(d.work.hours,24)||!nonnegative(d.work.commuteMinutes)||!nonnegative(d.work.workCost)||!['real','work'].includes(d.work.basis)||!['日常','购物','居住'].every(k=>nonnegative(d.budgets?.[k])))throw new Error('备份中的工作或预算数据不正确');for(const k of ['transactions','debts','goals','wishes','imports'])if(!Array.isArray(d[k])||d[k].length>10000)throw new Error('备份记录不完整');for(const t of d.transactions)if(!text(t.id)||!text(t.name)||!positive(t.amount)||!['expense','refund'].includes(t.type)||!date(t.date)||!text(t.account)||!['日常','购物','居住'].includes(t.category))throw new Error('备份消费记录不正确');for(const x of d.debts){if(!text(x.id)||!text(x.name)||!positive(x.principal)||!positive(x.terms,60)||!Array.isArray(x.schedule)||x.schedule.length>100)throw new Error('备份分期记录不正确');for(const r of x.schedule)if(!text(r.id)||!date(r.date)||![r.principal,r.interest,r.fee,r.total].every(nonnegative))throw new Error('备份期次不正确');}for(const g of d.goals)if(!text(g.id)||!text(g.name)||!positive(g.target)||!nonnegative(g.monthly)||!Array.isArray(g.entries)||g.entries.some(e=>!text(e.id)||!date(e.date)||typeof e.amount!=='number'||!Number.isFinite(e.amount)||Math.abs(e.amount)>99999999)||g.entries.reduce((s,e)=>s+e.amount,0)<0)throw new Error('备份目标记录不正确');for(const w of d.wishes)if(!text(w.id)||!text(w.name)||!positive(w.price))throw new Error('备份心愿不正确');if(d.imports.some(k=>!text(k,1000)))throw new Error('备份导入标记不正确');}
document.addEventListener('input',e=>{if(e.target.id==='calc-price'&&route?.type==='calculator'){const v=Number(e.target.value);if(Number.isFinite(v)&&v>=0&&v<=9999999){route.draft.price=v;$('#calc-results').innerHTML=calcResults(route.draft);}}else if(e.target.id==='minute-slider')$('#single-value').value=e.target.value;else if(e.target.id==='ledger-search'){ledgerSearch=e.target.value;const position=e.target.selectionStart;render();$('#ledger-search').focus();$('#ledger-search').setSelectionRange(position,position);}});
document.addEventListener('change',e=>{if(e.target.dataset.record!==undefined&&route?.type==='review'){route.records[Number(e.target.dataset.record)].selected=e.target.checked;const scroll=sheet.scrollTop;renderSheet();sheet.scrollTop=scroll;}});
backdrop.addEventListener('click',()=>close());
window.addEventListener('popstate',()=>{if(route)close(true);});
document.addEventListener('keydown',e=>{if(!route)return;if(e.key==='Escape')back();if(e.key==='Tab'){const items=[...sheet.querySelectorAll('button:not(:disabled),input:not(:disabled),select,a[href],summary')],first=items[0],last=items.at(-1);if(e.shiftKey&&(document.activeElement===first||document.activeElement===sheet)){e.preventDefault();last?.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus();}}});
render(false);
window.__timeworthPreview={navigate,reset:()=>{M.reset();navigate('home');},getState:()=>M.clone(state()),finance:M.finance,parseCSV,validateBackup};
if(M.storageError)toast('浏览器存储暂不可用，修改后请导出备份');
